export class OutlinePass extends Pass {
    @read public inputColor: TextureHandle;
    @read public inputDepth: TextureHandle;
    @create public outputColor: TextureHandle;

    constructor(colorIn: TextureHandle, depthIn: TextureHandle, colorOut: TextureHandle) {
