private buildDAGAndCull(): Pass[] {
    const activePasses = new Set<Pass>();
    const stack = this.passes.filter(p => p.isUnculled);

    while (stack.length > 0) {
        const pass = stack.pop()!;
        if (activePasses.has(pass)) continue;
        activePasses.add(pass);

        const activateCreator = (creator: Pass | null) => {
            if (creator && !activePasses.has(creator)) stack.push(creator);
        };

        for (const h of pass.textureReads) activateCreator(this.textures[h.index].creator);
        for (const h of pass.bufferReads) activateCreator(this.buffers[h.index].creator);
    }
    return this.passes.filter(p => activePasses.has(p) || p.isUnculled);
}

