import { FrameGraph, GraphBuilder, Pass, read, create, RenderContext, TextureHandle, createTextureHandle, IPlugin, RenderIO, Renderer } from "retiam";

// 1. Define the Custom Pass
export class CelOutlinePass extends Pass {
    @read public inputColor: TextureHandle;
    @read public inputDepth: TextureHandle;
    @create public outputColor: TextureHandle;

    private pipeline!: GPURenderPipeline;

    constructor(colorIn: TextureHandle, depthIn: TextureHandle, colorOut: TextureHandle) {
        super("CelOutlinePass");
        this.inputColor = colorIn;
        this.inputDepth = depthIn;
        this.outputColor = colorOut;
    }

    setup(builder: GraphBuilder): void {
        // Declare the output texture: matching canvas size & format
        builder.createTexture(this.outputColor, {
            format: navigator.gpu?.getPreferredCanvasFormat() || 'bgra8unorm',
            mode: 'relative',
            scale: 1.0,
            usage: GPUTextureUsage.RENDER_ATTACHMENT | GPUTextureUsage.TEXTURE_BINDING
        });
        builder.markUnculled();
    }

    execute(context: RenderContext): void {
        const { device, commandEncoder } = context;

        // Lazy initialize the WebGPU render pipeline
        if (!this.pipeline || this.isDirty) {
            const shaderCode = `
                @vertex fn vs(@builtin(vertex_index) i: u32) -> @builtin(position) vec4f {
                    var pos = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));
                    return vec4f(pos[i], 0.0, 1.0);
                }

                @group(0) @binding(0) var colorTex: texture_2d<f32>;
                @group(0) @binding(1) var depthTex: texture_depth_2d;

                @fragment fn fs(@builtin(position) pos: vec4f) -> @location(0) vec4f {
                    let coord = vec2i(pos.xy);
                    let baseColor = textureLoad(colorTex, coord, 0);

                    // Depth edge detection (Sobel filter):
                    let d0 = textureLoad(depthTex, coord, 0);
                    let dR = textureLoad(depthTex, coord + vec2i(1, 0), 0);
                    let dL = textureLoad(depthTex, coord + vec2i(-1, 0), 0);
                    let dU = textureLoad(depthTex, coord + vec2i(0, 1), 0);
                    let dD = textureLoad(depthTex, coord + vec2i(0, -1), 0);

                    let diff = abs(dR - d0) + abs(dL - d0) + abs(dU - d0) + abs(dD - d0);
                    let edge = select(0.0, 1.0, diff > 0.0005 && d0 > 0.0001);

                    return vec4f(mix(baseColor.rgb, vec3f(0.0), edge), baseColor.a);
                }
            `;

            this.pipeline = device.createRenderPipeline({
                layout: 'auto',
                vertex: { module: device.createShaderModule({ code: shaderCode }), entryPoint: 'vs' },
                fragment: {
                    module: device.createShaderModule({ code: shaderCode }),
                    entryPoint: 'fs',
                    targets: [{ format: navigator.gpu?.getPreferredCanvasFormat() || 'bgra8unorm' }]
                },
                primitive: { topology: 'triangle-list' }
            });
            this.isDirty = false;
        }

        // Retrieve physical WebGPU texture views from the context:
        const colorView = context.getTextureView(this.inputColor);
        const depthView = context.getTexture(this.inputDepth).createView({ aspect: 'depth-only' });
        const outputView = context.getTextureView(this.outputColor);

        const bindGroup = device.createBindGroup({
            layout: this.pipeline.getBindGroupLayout(0),
            entries: [
                { binding: 0, resource: colorView },
                { binding: 1, resource: depthView }
            ]
        });

        const pass = commandEncoder.beginRenderPass({
            colorAttachments: [{
                view: outputView,
                loadOp: 'clear',
                clearValue: { r: 0, g: 0, b: 0, a: 1 },
                storeOp: 'store'
            }]
        });

        pass.setPipeline(this.pipeline);
        pass.setBindGroup(0, bindGroup);
        pass.draw(3); // Fullscreen triangle
        pass.end();
    }
}

// 2. Wrap into an IPlugin
export class OutlinePlugin implements IPlugin {
    name = "OutlinePlugin";
    priority = 200;

    constructor(public options: { threshold?: number, thickness?: number } = {}) {}

    registerPasses(graph: FrameGraph, renderer: Renderer, io: RenderIO): RenderIO {
        const outlineOutput = createTextureHandle();
        const outlinePass = new CelOutlinePass(io.resolvedColor, io.depth, outlineOutput);

        graph.addPass(outlinePass);
        io.resolvedColor = outlineOutput; // Intercept the color chain!

        return io;
    }
}

